import os
from google.cloud import documentai_v1beta3 as documentai

def extract_receipt_fields(file_path):
    client = documentai.DocumentProcessorServiceClient()
    project_id = os.getenv('GOOGLE_CLOUD_PROJECT')
    location = 'us'
    processor_id = 'YOUR_PROCESSOR_ID'
    processor = f'projects/{project_id}/locations/{location}/processors/{processor_id}'

    with open(file_path, 'rb') as image:
        image_content = image.read()

    document = {'content': image_content, 'mime_type': 'application/pdf'}
    request = {'name': processor, 'document': document}

    result = client.process_document(request=request)
    document = result.document

    merchant = None
    tax = None
    total = None
    items = []

    for entity in document.entities:
        if entity.type_ == 'merchant':
            merchant = entity.mention_text
        elif entity.type_ == 'tax':
            tax = entity.mention_text
        elif entity.type_ == 'total':
            total = entity.mention_text
        elif entity.type_ == 'item':
            items.append(entity.mention_text)

    return {'merchant': merchant, 'tax': tax, 'total': total, 'items': items}

import json

def normalize_expense(extracted_fields):
    normalized_expense = {
        'vendor': extracted_fields.get('vendor', ''),
        'date': extracted_fields.get('date', ''),
        'total': extracted_fields.get('total', ''),
        'line_items': extracted_fields.get('line_items', [])
    }
    return json.dumps(normalized_expense, indent=2)

def validate_document_fields(extracted_fields):
    required_fields = ['vendor', 'date', 'total']
    for field in required_fields:
        if field not in extracted_fields or not extracted_fields[field]:
            return False
    return True

from typing import Dict

def create_document_request(file_path: str, project_id: str, location: str, processor_id: str) -> Dict:
    with open(file_path, 'rb') as image:
        image_content = image.read()

    document = {'content': image_content, 'mime_type': 'application/pdf'}
    processor = f'projects/{project_id}/locations/{location}/processors/{processor_id}'
    request = {'name': processor, 'document': document}
    return request

def parse_document_response(response):
    document = response.document
    extracted_fields = {}
    for entity in document.entities:
        extracted_fields[entity.type_] = entity.mention_text
    return extracted_fields

def summarize_invoice_fields(extracted_fields):
    summary = f"Invoice from {extracted_fields['vendor']} on {extracted_fields['date']} for a total of {extracted_fields['total']}"
    return summary

import re

def moderate_vendor_text(vendor_text):
    if re.search(r'\b(fraud|scam|phishing)\b', vendor_text, re.IGNORECASE):
        return 'Text contains sensitive content'
    return vendor_text

